<?php $u=require_user();$orders=q('SELECT * FROM compras WHERE usuario_id=? ORDER BY creado_en DESC,id DESC',[$u['id']])->fetchAll();?><div class="container py-5"><div class="kicker mb-3">TU HISTORIAL</div><h1 style="font-size:3rem">Mis compras</h1><?php if(!$orders):?><div class="surface p-5 mt-4">Todavía no has realizado compras. <a href="index.php?page=catalogo">Ir al catálogo</a></div><?php else: ?><div class="row g-3 mt-3"><?php foreach($orders as $o):$lines=q('SELECT * FROM detalle_compra WHERE compra_id=?',[$o['id']])->fetchAll();?><div class="col-12"><div class="surface p-4"><div class="d-flex justify-content-between flex-wrap"><h4>Pedido #<?=(int)$o['id']?></h4><span class="tag"><?=h($o['estado'])?> · <?=h($o['creado_en'])?></span></div><div class="table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody><?php foreach($lines as $line):?><tr><td><?=h($line['nombre_snapshot'])?></td><td><?=(int)$line['cantidad']?></td><td><?=money($line['subtotal'])?></td></tr><?php endforeach ?></tbody></table></div><div class="text-end fw-bold">Total <?=money($o['total'])?></div></div></div><?php endforeach ?></div><?php endif ?></div>
